import type { ActionContext } from '../../../data/action_context'
import type { AgentConversation } from '../../../data/data_types'
import { actionPromptDraftService } from '../../../services/actions/action_prompt_draft_service'
import { actionRunRegistry } from '../../../services/actions/action_run_registry'
import { dialogService } from '../../../services/dialog_service'
import type { ConversationPickerConversation } from './action_conversation_picker_data'
import { defaultLoadConversation, defaultLoadConversations } from '../run/popup/action_popup_defaults'

interface ActionConversationSnapshot {
    conversations: AgentConversation[]
    loading: boolean
    selectedConversation: AgentConversation | null
}

type Listener = () => void

function belongsToContext(conversation: ConversationPickerConversation, context: ActionContext) {
    return context.kind === 'project' || context.kind === 'merge-conflict'
        ? conversation.cardInternalId === null
        : conversation.cardInternalId === context.cardInternalId
}

function conversationTimestamp(conversation: ConversationPickerConversation) {
    const timestamp = Date.parse(conversation.startedAt)

    return Number.isNaN(timestamp) ? 0 : timestamp
}

export function conversationOptions<T extends ConversationPickerConversation>(
    conversations: T[],
    actionId: string,
    context: ActionContext,
    liveConversation: T | null,
) {
    const byId = new Map<string, T>()
    for (const conversation of conversations) {
        if (belongsToContext(conversation, context) && conversation.actionId === actionId) {
            byId.set(conversation.id, conversation)
        }
    }
    if (liveConversation && belongsToContext(liveConversation, context) && liveConversation.actionId === actionId) {
        byId.set(liveConversation.id, liveConversation)
    }

    return [...byId.values()].sort((left, right) => conversationTimestamp(right) - conversationTimestamp(left))
}

function latestWaitingConversation(conversations: AgentConversation[], actionId: string, context: ActionContext) {
    return conversations
        .filter((conversation) => belongsToContext(conversation, context)
            && conversation.actionId === actionId
            && conversation.status === 'waitingForInput')
        .sort((left, right) => conversationTimestamp(right) - conversationTimestamp(left))[0] ?? null
}

/** Owns history loading and selection for one popup action/context binding. */
export class ActionConversationStore {
    private readonly actionId: string
    private readonly context: ActionContext
    private initialSelectionConfigured = false
    private initialSelectionPath: string | null = null
    private loadRequest = 0
    private readonly listeners = new Set<Listener>()
    private snapshot: ActionConversationSnapshot = { conversations: [], loading: true, selectedConversation: null }

    constructor(actionId: string, context: ActionContext) {
        this.actionId = actionId
        this.context = context
    }

    readonly getSnapshot = () => this.snapshot

    readonly subscribe = (listener: Listener) => {
        this.listeners.add(listener)

        return () => this.listeners.delete(listener)
    }

    /** Sets one automatic selection consumed by initial history load. */
    configureInitialSelection(path: string | null) {
        if (this.initialSelectionConfigured) return

        this.initialSelectionConfigured = true
        this.initialSelectionPath = path
    }

    async load() {
        const request = this.loadRequest + 1
        this.loadRequest = request
        this.setSnapshot({ ...this.snapshot, loading: true })
        try {
            const conversations = await defaultLoadConversations(this.context)
            if (request !== this.loadRequest) return

            const run = actionRunRegistry.getActionRunStore(this.actionId, this.context)?.getSnapshot() ?? null
            const runActive = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
            const refreshedSelection = this.snapshot.selectedConversation
                ? conversations.find(({ path }) => path === this.snapshot.selectedConversation?.path) ?? this.snapshot.selectedConversation
                : null
            let selectedConversation = runActive
                ? refreshedSelection
                : refreshedSelection ?? latestWaitingConversation(conversations, this.actionId, this.context)
            const initialSelectionPath = this.initialSelectionPath
            this.initialSelectionPath = null
            if (!runActive && !selectedConversation && initialSelectionPath) {
                try {
                    const loadedConversation = await defaultLoadConversation(initialSelectionPath)
                    if (request !== this.loadRequest) return
                    this.validateSelection(loadedConversation)
                    selectedConversation = loadedConversation
                } catch (error) {
                    if (request !== this.loadRequest) return

                    this.setSnapshot({ conversations, loading: false, selectedConversation: null })
                    dialogService.error(error, { fallbackMessage: 'Could not load agent conversation' })
                    return
                }
            }
            this.setSnapshot({ conversations, loading: false, selectedConversation })
            if (selectedConversation) actionPromptDraftService.clearDraft(this.actionId, this.context, null)
        } catch (error) {
            if (request !== this.loadRequest) return

            this.setSnapshot({ conversations: [], loading: false, selectedConversation: null })
            dialogService.error(error, { fallbackMessage: 'Could not load agent conversations' })
        }
    }

    async select(path: string) {
        const request = this.loadRequest + 1
        this.loadRequest = request
        if (!path) {
            this.setSnapshot({ ...this.snapshot, selectedConversation: null })
            this.clearPromptDraft()
            return
        }

        try {
            const conversation = await defaultLoadConversation(path)
            if (request !== this.loadRequest) return
            this.validateSelection(conversation)

            this.setSnapshot({ ...this.snapshot, selectedConversation: conversation })
            this.clearPromptDraft()
        } catch (error) {
            if (request === this.loadRequest) {
                dialogService.error(error, { fallbackMessage: 'Could not load agent conversation' })
            }
        }
    }

    conversationOptions(liveConversation: AgentConversation | null): AgentConversation[]
    conversationOptions(liveConversation: ConversationPickerConversation | null): ConversationPickerConversation[]
    conversationOptions(liveConversation: ConversationPickerConversation | null) {
        const selected = this.snapshot.selectedConversation
        const conversations = selected ? [...this.snapshot.conversations, selected] : this.snapshot.conversations

        return conversationOptions(conversations, this.actionId, this.context, liveConversation)
    }

    continuationPath(liveConversation: AgentConversation | null) {
        return liveConversation?.path ?? this.snapshot.selectedConversation?.path ?? null
    }

    /** Applies one backend-returned conversation without another persistence round trip. */
    updateConversation(conversation: AgentConversation) {
        this.validateSelection(conversation)
        const conversations = this.snapshot.conversations.some(({ path }) => path === conversation.path)
            ? this.snapshot.conversations.map((current) => (current.path === conversation.path ? conversation : current))
            : [...this.snapshot.conversations, conversation]
        const selectedConversation = this.snapshot.selectedConversation?.path === conversation.path
            ? conversation
            : this.snapshot.selectedConversation
        this.setSnapshot({ ...this.snapshot, conversations, selectedConversation })
    }

    private clearPromptDraft() {
        const run = actionRunRegistry.getActionRunStore(this.actionId, this.context)?.getSnapshot() ?? null
        actionPromptDraftService.clearDraft(this.actionId, this.context, run)
    }

    private validateSelection(conversation: AgentConversation) {
        if (!belongsToContext(conversation, this.context)) throw new Error('Selected agent conversation belongs to another context')
        if (conversation.actionId !== this.actionId) throw new Error('Selected agent conversation belongs to another action')
    }

    private setSnapshot(snapshot: ActionConversationSnapshot) {
        this.snapshot = snapshot
        for (const listener of this.listeners) listener()
    }
}

import { useId, useMemo, useState } from 'react'
import { displayActionsForContext, projectContextWithWorktree, type ActionContext } from '../../../../data/action_context'
import { dataService } from '../../../../services/data/data_service'
import { isReleasedCardActionContext, RELEASED_CARD_RUN_MESSAGE } from '../../../../../../shared/released_card_actions.mjs'
import { useActions } from '../../../hooks/use_actions'
import { useProjectState } from '../../../hooks/use_project_state'
import { useProjectActionWorktree } from '../../../hooks/use_worktrees'
import { ActionPopupContent } from './action_popup_content'

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_content'

function resolvePopupTarget(context: ActionContext, snapshot: ReturnType<typeof useProjectState>['snapshot']) {
    if (context.kind === 'project') return 'Project'
    if (context.kind !== 'card') return null

    const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]

    return cards.find(({ header }) => header.internalId === context.cardInternalId)?.header.id ?? null
}

interface ActionPopupProps {
    anchorElement: HTMLElement | null
    context: ActionContext
    draggable?: boolean
    initialActionId?: string
    onActivate?: () => void
    onClose: () => void
    open?: boolean
    popupEntryId?: string
    stackPosition?: number
}

/** Universal action selector and run popup for the supplied context. */
export function ActionPopup(props: ActionPopupProps) {
    const { anchorElement, context, initialActionId, open } = props
    const { actions: loadedActions } = useActions()
    const { project, snapshot } = useProjectState()
    const projectActionWorktree = useProjectActionWorktree()
    const effectiveContext = useMemo(
        () => projectContextWithWorktree(context, projectActionWorktree),
        [context, projectActionWorktree],
    )
    const actions = useMemo(() => displayActionsForContext(loadedActions, effectiveContext), [effectiveContext, loadedActions])
    const [selectedActionId, setSelectedActionId] = useState<string | null>(initialActionId ?? actions[0]?.id ?? null)
    const [fullHeight, setFullHeight] = useState(false)
    const titleId = useId()
    // A run that edits its own card changes the context (state, title, worktree), so the
    // selected action can drop out of the filtered list mid-run. Keep it selectable instead
    // of closing the popup or silently switching to another action.
    const retainedAction = selectedActionId ? loadedActions.find(({ id }) => id === selectedActionId) ?? null : null
    const selectedAction = actions.find(({ id }) => id === selectedActionId) ?? retainedAction ?? actions[0] ?? null
    const selectableActions = selectedAction && !actions.some(({ id }) => id === selectedAction.id)
        ? [...actions, selectedAction]
        : actions
    const target = resolvePopupTarget(context, snapshot)
    const releasesFolder = dataService.getConfig()?.releasesFolder
    const readOnlyMessage = releasesFolder && isReleasedCardActionContext(effectiveContext, releasesFolder)
        ? RELEASED_CARD_RUN_MESSAGE
        : null

    const handleSelectAction = (actionId: string) => {
        setSelectedActionId(actionId)
    }

    const handleToggleFullHeight = () => setFullHeight((current) => !current)

    if (!selectedAction) return null

    return (
        <ActionPopupContent
            {...props}
            action={selectedAction}
            actions={selectableActions}
            assignmentContext={effectiveContext}
            baseContext={context}
            fullHeight={fullHeight}
            onSelectAction={handleSelectAction}
            onToggleFullHeight={handleToggleFullHeight}
            open={open ?? !!anchorElement}
            primaryPath={project?.rootPath ?? project?.id ?? null}
            readOnlyMessage={readOnlyMessage}
            target={target}
            titleId={titleId}
        />
    )
}

    async createProject(project: ProjectReference) {
        projectAccessService.requireWritable()
        const { config, storage } = this.dependencies.requireDependencies()
        const rawConfig = { ...configService.getProjectConfig(), backgroundShade: createRandomProjectBackgroundShade() }
        this.dependencies.replaceProject(await storage.createProject(project, config.workingFolder))
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot create a project without a project reference')

        await storage.commit({
            branch: currentProject.branch,
            files: [
                ...createDefaultActionFiles(config.actionsFolder),
                createProjectAgentTokenUsageFile(config.projectFolder),
            ],
            message: 'Add default MDÂ² actions',
        })
        await storage.saveProjectConfig(currentProject, rawConfig)
        telemetryService.trackEvent('create_project')

        return this.openProject(currentProject)
    }

    async openProject(project: ProjectReference) {
        const { storage } = this.dependencies.requireDependencies()
        await this.dependencies.flushPendingChanges()
        this.clearMarkdownReloadTimeout()
        this.clearMarkdownRemovalTimeouts()
        this.clearMergeConflictVerifyTimeout()
        const projectLoadToken = this.dependencies.beginProjectLoad()
        this.dependencies.resetAgentConversations()
        this.actionReloadChangesByPath.clear()
        this.markdownReloadEventsByPath = new Map()
        this.dependencies.replaceProject(project)

        try {
            const projectConfig = await this.loadProjectConfig(project)
            if (projectConfig === null) await this.saveMissingProjectConfig(project)

            const config = resolveProjectConfigPaths(configService.getProjectConfig())
            projectStatsService.bindProject({ config, project, storage })
            if (config.pushMode === 'manual') {
                await storage.restorePendingCommits?.(project)
                await this.loadPendingPush(project)
            }

            try {
                await projectAgentTokenUsageService.load(project, config, storage, reportAgentTokenUsageFailure)
            } catch (error) {
                reportAgentTokenUsageFailure(error)
            }

            await this.loadActions(project, config.actionsFolder)
            const projectFiles = await storage.loadProjectRoot(project, config.workingFolder)
            const repositoryFiles: string[] = []
            this.dependencies.replaceProjectFiles(projectFiles.files, config.workingFolder, repositoryFiles)
            await this.ensureCardInternalIds()
            await this.dependencies.migrateAgentLogReferences()
            this.tryStartProjectWatch()
            const currentSnapshot = this.dependencies.snapshot()
            if (!currentSnapshot) throw new Error('Project snapshot was not created')
            initializeMissingProjectStates(projectConfig ?? null, currentSnapshot)
            this.prepareAgentConversationLoading(projectLoadToken)
            this.dependencies.dispatchChanged()
            reportActionLoadIssues()

            void this.loadFullProjectInBackground(project, config.projectFolder, config.workingFolder, projectLoadToken)
            telemetryService.trackEvent('open_project')

            return currentSnapshot
        } catch (error) {
            this.clearFailedProjectLoad()
            dialogService.error(error, { fallbackMessage: 'Project could not be loaded', title: 'Project load failed' })
            markProjectLoadErrorReported(error)
            throw error
        }
    }

    async saveProjectConfig() {
        projectAccessService.requireWritable()
        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot save project config before a project is open')

        await storage.saveProjectConfig(currentProject, configService.getProjectConfig())
        this.dependencies.dispatchPersistenceChanged()
    }

    async updateCardSeparator(previousSeparator: CardSeparator, nextSeparator: CardSeparator) {
        projectAccessService.requireWritable()
        if (previousSeparator === nextSeparator) return 0

        const { config, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot rename card files before a project is open')

        await this.dependencies.flushPendingChanges()
        const projectFiles = await storage.loadProject(currentProject, config.projectFolder)
        const moves = planCardSeparatorMigration(projectFiles.files, previousSeparator, nextSeparator)
        if (moves.length === 0) return 0

        globalProgressService.start('Preparing card file names', moves.length)
        try {
            for (const [index, move] of moves.entries()) {
                globalProgressService.update(index, `Renaming ${move.fromPath}`)
                const inFlightCommitPaths = this.dependencies.commitPathsInFlight()
                inFlightCommitPaths.add(move.fromPath)
                inFlightCommitPaths.add(move.toPath)
                try {
                    await storage.moveFiles({
                        branch: currentProject.branch,
                        message: `Rename card file ${index + 1} of ${moves.length}`,
                        moves: [move],
                    })
                } finally {
                    inFlightCommitPaths.delete(move.fromPath)
                    inFlightCommitPaths.delete(move.toPath)
                }
                globalProgressService.update(index + 1, `Renamed ${move.toPath}`)
            }

            if (config.pushMode === 'auto') await storage.push(currentProject)
            await this.reloadCurrentProjectSnapshot()

            return moves.length
        } finally {
            globalProgressService.finish()
        }
    }

    async loadProjectAsset(path: string): Promise<ProjectAsset> {
        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot load a project asset before a project is open')
        if (!storage.loadProjectAsset) throw new Error('Project asset loading is not available')

        return storage.loadProjectAsset(currentProject, path)
    }

    async switchBranch(branch: string) {
        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot switch branch before a project is open')

        await this.dependencies.flushPendingChanges()
        const project = await storage.checkoutBranch(currentProject, branch)

        return this.openProject(project)
    }

    async push() {
        projectAccessService.requireWritable()
        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot push before a project is open')

        await storage.push(currentProject)
        this.dependencies.dispatchPersistenceChanged()
    }

    async pull() {
        projectAccessService.requireWritable()
        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot pull before a project is open')
        if (!storage.pull) throw new Error('Pulling the primary worktree is not available')

        await storage.pull(currentProject)
    }

    async reloadCurrentProjectSnapshot() {
        const { config, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot reload project snapshot before a project is open')

        const projectLoadToken = this.dependencies.beginProjectLoad()
        this.prepareAgentConversationLoading(projectLoadToken)
        const projectFiles = await storage.loadProject(currentProject, config.projectFolder)
        const repositoryFiles = await storage.listRepositoryFiles(currentProject)
        this.dependencies.replaceProjectFiles(projectFiles.files, config.workingFolder, repositoryFiles)
        await this.ensureCardInternalIds()
        await this.dependencies.migrateAgentLogReferences()
        this.dependencies.markFullProjectLoaded()
        this.dependencies.dispatchChanged()
        return this.dependencies.snapshot()
    }

    stopProjectWatch() {
        if (!this.watchCleanup) return

        this.watchCleanup()
        this.watchCleanup = null
    }

    async reloadConflictPaths(paths: string[]) {
        const { config } = this.dependencies.requireDependencies()
        for (const path of paths) {
            if (!isProjectMarkdownPath(path, config.projectFolder)) continue
            this.markdownReloadEventsByPath.set(path, { changeKind: 'unknown', path })
        }
        if (this.markdownReloadEventsByPath.size === 0) return

        await this.reloadMarkdownFilesFromWatchEvents()
    }

    private clearFailedProjectLoad() {
        this.stopProjectWatch()
        this.clearActionReloadTimeout()
        this.clearMarkdownReloadTimeout()
        this.clearMarkdownRemovalTimeouts()
        this.clearMergeConflictVerifyTimeout()
        this.dependencies.beginProjectLoad()
        this.dependencies.resetAgentConversations()
        projectAgentTokenUsageService.clear()
        projectStatsService.clear()
        this.dependencies.clearLoadedProject()
        this.actionReloadChangesByPath.clear()
        this.markdownReloadEventsByPath.clear()
        actionService.clear()
        worktreeService.clear()
        this.dependencies.dispatchChanged()
    }

    private async loadProjectConfig(project: ProjectReference) {
        const { storage } = this.dependencies.requireDependencies()

        try {
            const projectConfig = await storage.loadProjectConfig(project)
            configService.loadProjectConfig(projectConfig)

            return projectConfig
        } catch (error) {
            if (error instanceof GithubUnauthorizedError) throw error

            configService.loadProjectConfig(null)
            reportOptionalProjectLoadFailure('Project configuration', error)

            return undefined
        }
    }

    }

    async openProject(project: ProjectReference) {
        const { storage } = this.dependencies.requireDependencies()
        await this.dependencies.flushPendingChanges()
        this.clearMarkdownReloadTimeout()
        this.clearMarkdownRemovalTimeouts()
        this.clearMergeConflictVerifyTimeout()
        const projectLoadToken = this.dependencies.beginProjectLoad()
        this.dependencies.resetAgentConversations()
        this.actionReloadChangesByPath.clear()
        this.markdownReloadEventsByPath = new Map()
        this.dependencies.replaceProject(project)

        try {
            const projectConfig = await this.loadProjectConfig(project)
            if (projectConfig === null) await this.saveMissingProjectConfig(project)

            const config = resolveProjectConfigPaths(configService.getProjectConfig())
            projectStatsService.bindProject({ config, project, storage })
            if (config.pushMode === 'manual') {
                await storage.restorePendingCommits?.(project)
                await this.loadPendingPush(project)
            }

            try {
                await projectAgentTokenUsageService.load(project, config, storage, reportAgentTokenUsageFailure)
            } catch (error) {
                reportAgentTokenUsageFailure(error)
            }

            await this.loadActions(project, config.actionsFolder)
            const projectFiles = await storage.loadProjectRoot(project, config.workingFolder)
            const repositoryFiles: string[] = []
            this.dependencies.replaceProjectFiles(projectFiles.files, config.workingFolder, repositoryFiles)
