    render(
        <>
            <CardRunButton
                card={Card}
                context={cardContext(Card, DEFAULT_CARD_TYPES)}
            />
            <CardActionPopupHost />
        </>,
        { wrapper: AppThemeProvider },
    )
}

describe('CardRunButton', () => {
    beforeEach(() => {
